// Periskopos endpoint for __APP_NAME_COMMENT__ — a Supabase Edge Function.
//
// Generated by Periskopos (protocol version 1). Put this file at
//   supabase/functions/periskopos/index.ts
// then set the secret and deploy (the generator shows the exact commands).
// It must be deployed WITHOUT JWT verification (--no-verify-jwt): Ground
// Control authenticates with its own bearer secret, which is not a JWT.
//
// What it does: answers Periskopos's local server (and only it: no CORS
// headers, every request needs the secret) with
//   GET  /manifest          what this app is and which capabilities it has
//   GET  /metrics           numbers to show on the Fleet and the app page
//   GET  /actions           buttons Periskopos may press
//   POST /actions/<id>      press one
//
// Fill in the three functions marked FILL IN below. Return counts and short
// strings only: never emails, names or other personal data.

// ── Settings ────────────────────────────────────────────────────────────

const APP_NAME = "__APP_NAME__";
const CAPABILITIES: string[] = JSON.parse('["__CAPABILITIES__"]');
const PROTOCOL = 1;

// ── FILL IN ─────────────────────────────────────────────────────────────

export type Metric = { id: string; label: string; value: number | string; hint?: string };
export type ActionDef = { id: string; label: string; description?: string; confirm?: boolean; danger?: boolean };

// A Supabase client with the service role (admin) key. Both variables are
// provided to Edge Functions automatically. Only reads and writes in this
// file ever use it, and it never leaves this function.
//
//   const supabase = await admin();
//   const { count } = await supabase.from("my_table").select("*", { count: "exact", head: true });
export async function admin() {
  const { createClient } = await import("npm:@supabase/supabase-js@2");
  return createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!, {
    auth: { persistSession: false },
  });
}

// FILL IN: the numbers worth seeing at a glance. Counts, never personal data.
// Periskopos shows the first three on the Fleet.
