// ── The protocol (leave as is) ──────────────────────────────────────────

export type Hooks = {
  secret: () => string | undefined;
  name?: string;
  version?: string;
  commit?: string;
  capabilities?: string[];
  getMetrics?: () => Promise<Metric[]>;
  listActions?: () => Promise<ActionDef[]>;
  runAction?: (id: string) => Promise<{ ok: boolean; message: string }>;
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });

// Compares in constant time, so the answer doesn't depend on how many
// leading characters matched.
function same(a: string, b: string): boolean {
  const x = new TextEncoder().encode(a);
  const y = new TextEncoder().encode(b);
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) diff |= (x[i] ?? 0) ^ (y[i] ?? 0);
  return diff === 0;
}

export function createHandler(hooks: Hooks) {
  const capabilities = hooks.capabilities ?? CAPABILITIES;
  return async function handle(req: Request): Promise<Response> {
    // No secret configured means nothing is served: fail closed.
    const secret = hooks.secret();
    if (!secret || secret.length < 32) return json({ error: "Not configured: set PERISKOPOS_SECRET" }, 503);

    const given = /^Bearer (.+)$/.exec(req.headers.get("authorization") ?? "")?.[1];
    if (!given || !same(given, secret)) return json({ error: "Unauthorized" }, 401);

    // The function's own name is a prefix of the path; only the end matters.
    const path = new URL(req.url).pathname.replace(/\/+$/, "");
    try {
      if (req.method === "GET" && /\/manifest$/.test(path)) {
        return json({
          protocol: PROTOCOL,
          app: { name: hooks.name ?? APP_NAME, ...(hooks.version ? { version: hooks.version } : {}), ...(hooks.commit ? { commit: hooks.commit } : {}) },
          capabilities,
        });
      }
      if (req.method === "GET" && /\/metrics$/.test(path) && capabilities.includes("metrics")) {
        return json({ metrics: await (hooks.getMetrics ?? getMetrics)(), at: new Date().toISOString() });
      }
      if (req.method === "GET" && /\/actions$/.test(path) && capabilities.includes("actions")) {
        return json({ actions: await (hooks.listActions ?? listActions)() });
      }
      const action = req.method === "POST" ? /\/actions\/([\w-]+)$/.exec(path) : null;
      if (action && capabilities.includes("actions")) {
        const known = (await (hooks.listActions ?? listActions)()).some((a) => a.id === action[1]);
        if (!known) return json({ error: `Unknown action "${action[1]}"` }, 404);
        return json(await (hooks.runAction ?? runAction)(action[1]));
      }
      return json({ error: "Not found" }, req.method === "GET" || req.method === "POST" ? 404 : 405);
    } catch (err) {
      // The message goes to Periskopos only; it is shown to me, not to users.
      return json({ error: err instanceof Error ? err.message : "Something went wrong" }, 500);
    }
  };
}

export const handler = createHandler({
  secret: () => (typeof Deno !== "undefined" ? Deno.env.get("PERISKOPOS_SECRET") : undefined),
  version: typeof Deno !== "undefined" ? Deno.env.get("APP_VERSION") : undefined,
  commit: typeof Deno !== "undefined" ? Deno.env.get("APP_COMMIT") : undefined,
});

if (typeof Deno !== "undefined" && typeof Deno.serve === "function") Deno.serve(handler);
